    vec3 f = normalize(sub(center, eye));
    vec3 s = normalize(cross(f, up));
    vec3 u = cross(s, f);

    mat4 m;
    m[0].x = s.x; m[0].y = s.y; m[0].z = s.z; m[0].w = -dot(s, eye);
